 // Fuji
 const by=-14,ty=13,bw=64,tw=4.2,hw=y=>tw+(bw/2-tw)*Math.pow((ty-y)/(ty-by),1.7);const fp=[];for(let y=by;y<=ty;y+=1)fp.push([-hw(y),y]);for(let y=ty;y>=by;y-=1)fp.push([hw(y),y]);
